import type { ITodoListSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSystemSetting";

/**
 * Validate admin-scoped retrieval of a specific system setting by key.
 *
 * 1. Register an admin with random credentials and log in (acquire privileges).
 * 2. With the admin session, find an existing system setting via direct fetch
 *    (this provides a valid key).
 * 3. Use the GET /todoList/admin/systemSettings/{key} endpoint as admin and verify
 *    the returned record:
 *
 * - It should have all fields present (id, key, value, description, created_at,
 *   updated_at).
 * - The key and value fields should match those obtained previously.
 *
 * 4. Attempt to fetch the same setting using an unauthenticated connection and
 *    verify access is denied (authorization required).
 */
export async function test_api_system_setting_detail_read_admin_access(
  connection: api.IConnection,
) {
  // Register admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPayload = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(12) as string &
      tags.MinLength<8> &
      tags.Format<"password">,
    href: "https://admin.test.example.com/register",
    referrer: "https://admin.test.example.com/",
  } satisfies ITodoListAdmin.IJoin;
  const admin = await api.functional.auth.admin.join(connection, {
    body: adminPayload,
  });
  typia.assert(admin);

  // As admin, fetch a known system setting (simulate existence, use random key-value from the previous fetch)
  // Find a valid key for demonstration by fetching directly using the system's random method
  const settingSample = typia.random<ITodoListSystemSetting>();

  // Simulate inserting this setting in a real environment, here assumed already exists (since there is no create endpoint exposed)

  // Get the setting as the admin
  const setting = await api.functional.todoList.admin.systemSettings.at(
    connection,
    { key: settingSample.key },
  );
  typia.assert(setting);
  TestValidator.equals(
    "system setting key matches",
    setting.key,
    settingSample.key,
  );
  TestValidator.predicate(
    "system setting id is uuid",
    typeof setting.id === "string" && setting.id.length > 0,
  );
  TestValidator.predicate(
    "system setting value is present",
    typeof setting.value === "string" && setting.value.length > 0,
  );
  TestValidator.predicate(
    "system setting created_at valid ISO",
    typeof setting.created_at === "string" && setting.created_at.length > 0,
  );
  TestValidator.predicate(
    "system setting updated_at valid ISO",
    typeof setting.updated_at === "string" && setting.updated_at.length > 0,
  );
  // description is optional, allow null/undefined
  TestValidator.predicate(
    "system setting description field allowed",
    setting.description === undefined ||
      setting.description === null ||
      typeof setting.description === "string",
  );

  // Try unauthorized (unauthenticated) fetch for the same key
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized access is denied", async () => {
    await api.functional.todoList.admin.systemSettings.at(unauthConn, {
      key: settingSample.key,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUserSession";
import type { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";
import type { ITodoListUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUserSession";

/**
 * Validate admin-driven audit of user session history with privacy and access
 * control.
 *
 * 1. Register a new admin with sufficient context (IP, href, referrer).
 * 2. With admin privileges, issue a session audit request for a random user UUID,
 *    using pagination and search filters via PATCH
 *    /todoList/admin/users/{userId}/sessions.
 * 3. Validate paginated session results: confirm each session summary omits
 *    sensitive tokens, includes proper audit metadata (id, timestamps, IP,
 *    href, referrer), and has correct pagination fields.
 * 4. Switch to unauthenticated context (simulate missing Authorization), attempt
 *    session audit and confirm error is thrown.
 * 5. Re-authenticate as admin and confirm endpoint accepts access only for admin
 *    actors.
 */
export async function test_api_admin_user_session_audit_by_admin(
  connection: api.IConnection,
) {
  // 1. Register new admin
  const adminJoin = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    ip: typia.random<string & tags.Format<"ipv4">>(),
    href: "https://admin-testing.example.com/signup",
    referrer: "https://admin-testing.example.com/",
  } satisfies ITodoListAdmin.IJoin;
  const admin: ITodoListAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoin });
  typia.assert(admin);
  TestValidator.predicate("admin account is not locked", !admin.is_locked);

  // 2. Audit user sessions as admin
  const targetUserId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  const sessionFilter = {
    page: 1,
    limit: 10,
    order_by: RandomGenerator.pick(["created_at", "expired_at"] as const),
    order: RandomGenerator.pick(["asc", "desc"] as const),
    search: undefined,
  } satisfies ITodoListUserSession.IRequest;

  const auditResult: IPageITodoListUserSession.ISummary =
    await api.functional.todoList.admin.users.sessions.index(connection, {
      userId: targetUserId,
      body: sessionFilter,
    });
  typia.assert(auditResult);

  // 3. Validate session summary paginated response structure
  TestValidator.predicate(
    "correct pagination structure present",
    typeof auditResult.pagination.current === "number" &&
      typeof auditResult.pagination.limit === "number" &&
      typeof auditResult.pagination.records === "number" &&
      typeof auditResult.pagination.pages === "number",
  );

  for (const session of auditResult.data) {
    typia.assert(session);
    TestValidator.predicate(
      "session summary omits sensitive data",
      typeof (session as any).token === "undefined",
    );
    TestValidator.predicate(
      "session summary has ID",
      typeof session.id === "string",
    );
    TestValidator.predicate(
      "session has creation timestamp",
      typeof session.created_at === "string",
    );
    TestValidator.predicate("session has IP", typeof session.ip === "string");
    TestValidator.predicate(
      "session has href",
      typeof session.href === "string",
    );
    TestValidator.predicate(
      "session has referrer",
      typeof session.referrer === "string",
    );
    // expired_at may be null or undefined for active sessions
    if (session.expired_at !== null && session.expired_at !== undefined)
      TestValidator.predicate(
        "expired_at is ISO date",
        typeof session.expired_at === "string",
      );
  }

  // 4. Simulate unauthenticated context - remove Authorization, expect error
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error(
    "unauthenticated non-admin cannot audit user session history",
    async () => {
      await api.functional.todoList.admin.users.sessions.index(unauthConn, {
        userId: targetUserId,
        body: sessionFilter,
      });
    },
  );

  // 5. Re-authenticate as another admin, expect success
  const newAdminJoin = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    ip: typia.random<string & tags.Format<"ipv4">>(),
    href: "https://admin-testing.example.com/signup2",
    referrer: "https://admin-testing.example.com/",
  } satisfies ITodoListAdmin.IJoin;

  const newAdmin: ITodoListAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: newAdminJoin });
  typia.assert(newAdmin);

  const auditResult2: IPageITodoListUserSession.ISummary =
    await api.functional.todoList.admin.users.sessions.index(connection, {
      userId: targetUserId,
      body: sessionFilter,
    });
  typia.assert(auditResult2);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";

/**
 * Validate an administrator's ability to revoke their own session and ensure
 * permanent invalidation.
 *
 * 1. Register a new admin (simulate a fresh session), ensuring unique
 *    email/password and context.
 * 2. Use returned credentials (adminId, token) as authentication.
 * 3. Perform DELETE /todoList/admin/admins/{adminId}/sessions/{sessionId}, using a
 *    random UUID (since sessionId not retrievable).
 * 4. Attempt authenticated operation with non-existent session, expecting error
 *    (logout effect / invalid session).
 * 5. Attempt to delete a session as another admin, expect security error.
 *
 * This sequence tests privilege enforcement, valid session matching, and proper
 * error responses for invalid operations, within API/DTO constraints.
 */
export async function test_api_admin_session_delete_by_admin(
  connection: api.IConnection,
) {
  // 1. Register first admin (gives us an adminId and tokens)
  const adminBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    href: "https://admin-join.example.com/signup",
    referrer: "https://admin-portal.example.com/welcome",
  } satisfies ITodoListAdmin.IJoin;
  const authorized1 = await api.functional.auth.admin.join(connection, {
    body: adminBody,
  });
  typia.assert(authorized1);

  // 2. Attempt to delete a (random) session for this admin (since actual sessionId unavailable):
  const randomSessionId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("cannot delete non-existent session", async () => {
    await api.functional.todoList.admin.admins.sessions.erase(connection, {
      adminId: authorized1.id,
      sessionId: randomSessionId,
    });
  });

  // 3. Register a second admin, try to delete a session with first admin's id (should also fail)
  const adminBody2 = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(14),
    href: "https://admin-join2.example.com/signup",
    referrer: "https://admin-portal.example.com/welcome",
  } satisfies ITodoListAdmin.IJoin;
  const authorized2 = await api.functional.auth.admin.join(connection, {
    body: adminBody2,
  });
  typia.assert(authorized2);
  await TestValidator.error(
    "other admin cannot delete session for unrelated admin",
    async () => {
      await api.functional.todoList.admin.admins.sessions.erase(connection, {
        adminId: authorized2.id,
        sessionId: randomSessionId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListTodo";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Test authenticated user searching and filtering their own todo list.
 *
 * 1. Register a new user to establish authentication context
 * 2. Since we cannot create todos (no create API), the list should be empty.
 * 3. Perform paginated search/filter API calls with various parameters:
 *
 *    - No filters
 *    - Completed: true
 *    - Completed: false
 *    - Search: random string
 *    - Include_deleted: true
 *    - Page: 1, 2, limit: 1, 10, 100
 * 4. Ensure all responses have empty data arrays and correct pagination fields.
 * 5. Assert the responses are strictly for the user, and error/edge cases like
 *    page overflow return empty data.
 */
export async function test_api_todo_list_search_and_filter_by_user(
  connection: api.IConnection,
) {
  // 1. Register user
  const email =
    RandomGenerator.name(1) +
    "_" +
    RandomGenerator.alphabets(8) +
    "@autobe-e2e.com";
  const password = RandomGenerator.alphaNumeric(12);
  const joinResult = await api.functional.auth.user.join(connection, {
    body: {
      email,
      password,
    } satisfies ITodoListUser.ICreate,
  });
  typia.assert(joinResult);
  TestValidator.predicate(
    "token must be present",
    typeof joinResult.token.access === "string" &&
      joinResult.token.access.length > 0,
  );

  // 2. Search / filter with various combinations - expect empty result
  // Utility function to test index with a given request
  async function validateSearch(
    body: ITodoListTodo.IRequest,
    description: string,
  ) {
    const output = await api.functional.todoList.user.todos.index(connection, {
      body,
    });
    typia.assert(output);
    TestValidator.equals(
      description + " - pagination current page",
      output.pagination.current,
      (body.page ?? 1) satisfies number as number,
    );
    TestValidator.equals(
      description + " - pagination limit",
      output.pagination.limit,
      (body.limit ?? 100) satisfies number as number,
    );
    TestValidator.equals(
      description + " - records",
      output.pagination.records,
      0,
    );
    TestValidator.predicate(
      description + " - data is empty",
      Array.isArray(output.data) && output.data.length === 0,
    );
  }

  // Basic no-filter search
  await validateSearch({}, "no filter");
  // completed: true
  await validateSearch({ completed: true }, "completed: true");
  // completed: false
  await validateSearch({ completed: false }, "completed: false");
  // search: random string
  await validateSearch(
