import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate the administrator's ability to hard delete a todo entry, permanently
 * erasing it from the system.
 *
 * This test covers compliance auditing, role-based access, and
 * irrecoverability:
 *
 * 1. Register a new admin and login as admin.
 * 2. Register a user, login as the user, and create a todo.
 * 3. Log back in as admin and permanently hard delete the todo.
 * 4. Confirm (as user) that the todo is completely erased:
 *
 *    - Cannot retrieve by id
 *    - Does not appear in listings
 *    - Cannot undo, restore, or soft delete
 * 5. Try unauthorized access: confirm that regular users cannot use the admin
 *    delete endpoint.
 * 6. Confirm that all steps are logged or traced for compliance/audit (note: if
 *    audit logs are available via API, validate presence).
 */
export async function test_api_admin_hard_delete_todo(
  connection: api.IConnection,
) {
  // Step 1: Register and authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword: string & tags.MinLength<8> & tags.Format<"password"> =
    RandomGenerator.alphaNumeric(12);
  const adminJoin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://admin.example.com/register",
      referrer: "https://admin.example.com/landing",
      ip: null,
    } satisfies ITodoListAdmin.IJoin,
  });
  typia.assert(adminJoin);
  // Explicit admin login (token swapping)
  const adminLogin = await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://admin.example.com/login",
      referrer: "https://admin.example.com/landing",
      ip: null,
    } satisfies ITodoListAdmin.ILogin,
  });
  typia.assert(adminLogin);

  // Step 2: Register and authenticate as a user
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword: string = RandomGenerator.alphaNumeric(12);
  const userJoin = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
    } satisfies ITodoListUser.ICreate,
  });
  typia.assert(userJoin);
  // Login as user (token swapping)
  const userLogin = await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword as string &
        tags.MinLength<8> &
        tags.Format<"password">,
    } satisfies ITodoListUser.ILogin,
  });
  typia.assert(userLogin);

  // Step 3: Create a todo as the user
  const todo = await api.functional.todoList.user.todos.create(connection, {
    body: {
      description: RandomGenerator.paragraph({
        sentences: 3,
        wordMin: 4,
        wordMax: 10,
      }) as string & tags.MaxLength<255>,
      completed: false,
    } satisfies ITodoListTodo.ICreate,
  });
  typia.assert(todo);

  // Step 4: Log back in as admin and hard delete the todo
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://admin.example.com/login",
      referrer: "https://admin.example.com/landing",
      ip: null,
    } satisfies ITodoListAdmin.ILogin,
  });
  // Perform hard delete as admin
  const erased = await api.functional.todoList.admin.todos.erase(connection, {
    todoId: todo.id,
  });
  typia.assert(erased);
  TestValidator.equals("erased todo id matches", erased.id, todo.id);

  // Step 5: Verify as user that todo is no longer accessible (simulate access denied or not found)
  await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword as string &
        tags.MinLength<8> &
        tags.Format<"password">,
    } satisfies ITodoListUser.ILogin,
  });
  // Attempt to use admin delete endpoint (permission should be denied)
  await TestValidator.error(
    "user cannot perform admin hard delete",
    async () => {
      await api.functional.todoList.admin.todos.erase(connection, {
        todoId: todo.id,
      });
    },
  );
  // Confirm no access to the erased todo (simulate not-found error by trying to delete again as admin)
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://admin.example.com/login",
      referrer: "https://admin.example.com/landing",
      ip: null,
    } satisfies ITodoListAdmin.ILogin,
  });
  await TestValidator.error(
    "cannot hard delete already-erased todo again",
    async () => {
      await api.functional.todoList.admin.todos.erase(connection, {
        todoId: todo.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoListTodoAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListTodoAuditLog";
import type { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListTodoAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodoAuditLog";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate that administrators can search and filter paginated audit logs for a
 * specific todo item.
 *
 * Scenario:
 *
 * 1. Register an admin and a regular user with unique credentials.
 * 2. Authenticate as admin, then as user. Create a todo as the user.
 * 3. Perform a few modifications on the todo as the user to generate audit logs.
 * 4. Authenticate as admin, then search the audit logs for that todo with various
 *    filter queries: a. by actor_user_id b. by action type (e.g., "created",
 *    "updated") c. by after/before time window d. test pagination (page,
 *    limit)
 * 5. Check that all returned audit entries have correct todo_id, appropriate
 *    actors/actions, and within the filtered ranges.
 * 6. Confirm that a regular user is forbidden from accessing the audit log search
 *    endpoint.
 */
export async function test_api_admin_todo_audit_log_search(
  connection: api.IConnection,
) {
  // 1. Register admin and user with unique credentials
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminJoinResult = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://admin.origin/",
      referrer: "https://admin.origin/ref",
    },
  });
  typia.assert(adminJoinResult);

  const userEmail = typia.random<string & tags.Format<"email">>();
  const userPassword = RandomGenerator.alphaNumeric(12);
  const userJoinResult = await api.functional.auth.user.join(connection, {
    body: {
      email: userEmail,
      password: userPassword,
    },
  });
  typia.assert(userJoinResult);

  // 2. Login as user for todo creation
  await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
    },
  });

  const todo = await api.functional.todoList.user.todos.create(connection, {
    body: {
      description: RandomGenerator.paragraph({ sentences: 3 }),
      completed: false,
    },
  });
  typia.assert(todo);

  // 3. Perform some updates on the todo to generate audit logs
  // (no explicit update endpoint given, but creation itself produces a 'created' log)

  // 4. Login as admin
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://admin.origin/",
      referrer: "https://admin.origin/ref",
    },
  });

  // 5. Query audit logs with varying filters (by user actor, action, pagination)
  const requestBase = {
    actor_user_id: userJoinResult.id,
    actor_admin_id: null,
    action: null,
    after: null,
    before: null,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number &
      tags.Type<"int32"> &
      tags.Minimum<1> &
      tags.Maximum<100>,
  } satisfies ITodoListTodoAuditLog.IRequest;

  const auditPage = await api.functional.todoList.admin.todos.auditLogs.index(
    connection,
    {
      todoId: todo.id,
      body: requestBase,
    },
  );
  typia.assert(auditPage);
  TestValidator.equals(
    "all audit logs belong to the todo",
    auditPage.data.every((log) => log.todo_id === todo.id),
    true,
  );
  TestValidator.predicate(
    "at least one log of action 'created' exists",
    auditPage.data.some((log) => log.action === "created"),
  );
  if (auditPage.data.length > 0) {
    TestValidator.equals(
      "all logs actor_user_id equals user id",
      auditPage.data.every((log) => log.actor_user_id === userJoinResult.id),
      true,
    );
  }

  // 6. Query by nonexistent action
  const byAction = await api.functional.todoList.admin.todos.auditLogs.index(
    connection,
    {
      todoId: todo.id,
      body: { ...requestBase, action: "deleted" },
    },
  );
  typia.assert(byAction);
  if (byAction.data.length > 0) {
    TestValidator.equals(
      "all logs are 'deleted' actions",
      byAction.data.every((log) => log.action === "deleted"),
      true,
    );
  }

  // 7. Pagination test (limit 1)
  const paged = await api.functional.todoList.admin.todos.auditLogs.index(
    connection,
    {
      todoId: todo.id,
      body: { ...requestBase, limit: 1 },
    },
  );
  typia.assert(paged);
  TestValidator.equals("pagination works (limit 1)", paged.pagination.limit, 1);
  TestValidator.predicate("returned at most one log", paged.data.length <= 1);

  // 8. Confirm forbidden for non-admin (login back as user, then try search)
  await api.functional.auth.user.login(connection, {
    body: {
      email: userEmail,
      password: userPassword,
    },
  });
  await TestValidator.error(
    "user forbidden from viewing audit logs",
    async () => {
      await api.functional.todoList.admin.todos.auditLogs.index(connection, {
        todoId: todo.id,
        body: requestBase,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";

/**
 * Validate that an admin can update an existing todo with valid changes.
 *
 * This test covers the workflow:
 *
 * 1. Register a new admin and authenticate.
 * 2. (Setup) The admin is assumed to have access to all todos, but since there is
 *    no admin create, we simulate with random uuid and random initial todo
 *    object (as backend would allow admin-level patch).
 * 3. The admin submits an update to the todo, changing both description and
 *    completion state.
 * 4. Assert that the returned todo reflects updates.
 * 5. Ensure timestamps update appropriately.
 */
export async function test_api_todo_admin_update_basic(
  connection: api.IConnection,
) {
  // 1. Register and authenticate admin
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<
    string & tags.MinLength<8> & tags.Format<"password">
  >();
  const joinInput = {
    email,
    password,
    href: "https://example.com/join",
    referrer: "https://example.com/landing",
    ip: undefined,
  } satisfies ITodoListAdmin.IJoin;
  const admin: ITodoListAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: joinInput });
  typia.assert(admin);

  // -- (simulate an existing todo for admin update: usually this would require a user-owned todo to be present)
  //     -- For E2E, we mock with random existing todo: in reality, this should come from a setup step or fixture
  const originalTodo: ITodoListTodo = typia.random<ITodoListTodo>();

  // 2. Define update payload
  const newDescription = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 3,
    wordMax: 40,
  }); // short valid, unique
  const completed = !originalTodo.completed;
  const updateBody = {
    description: newDescription,
    completed,
  } satisfies ITodoListTodo.IUpdate;

  // 3. Admin updates the todo
  const updated: ITodoListTodo =
    await api.functional.todoList.admin.todos.update(connection, {
      todoId: originalTodo.id,
      body: updateBody,
    });
  typia.assert(updated);

  // 4. Description is updated
  TestValidator.equals(
    "todo description updated",
    updated.description,
    newDescription,
  );
  // 5. Completion state is toggled
  TestValidator.equals(
    "todo completed flag updated",
    updated.completed,
    completed,
  );

  // 6. updated_at is later than original
  TestValidator.predicate(
    "updated_at should be newer than before",
    new Date(updated.updated_at) > new Date(originalTodo.updated_at),
  );

  // 7. completed_at updated properly
  if (completed) {
    // If marked as complete, must be set
    TestValidator.predicate(
      "completed_at must be present when completed",
      updated.completed_at !== null && updated.completed_at !== undefined,
    );
    // If original was not completed or completed_at was null, must be newer
    if (
      originalTodo.completed_at !== null &&
      originalTodo.completed_at !== undefined
    ) {
      TestValidator.predicate(
        "completed_at updated or unchanged if already complete",
        new Date(updated.completed_at!) >= new Date(originalTodo.completed_at!),
      );
    }
  } else {
    // If marked as incomplete, must be null
    TestValidator.equals(
      "completed_at cleared when incomplete",
      updated.completed_at,
      null,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";

/**
 * Validates that admin updates to todo descriptions enforce uniqueness and
 * length constraints
 *
 * This test confirms that an administrator is prevented from violating core
 * business rules when updating a user's todo description:
 *
 * 1. Description must be unique among the user's todos (no duplicates)
 * 2. Description cannot exceed 255 characters
 * 3. Description cannot be empty or consist solely of whitespace
 *
 * Steps:
 *
 * 1. Register and authenticate as admin
 * 2. Create two distinct todos for the same user using admin privilege
 * 3. Attempt to update the second todo to have the same description as the first -
 *    expect rejection
 * 4. Attempt to update description to a string longer than 255 characters - expect
 *    rejection
 * 5. Attempt to update description to an empty string - expect rejection
 * 6. Attempt to update description to a whitespace-only string - expect rejection
 */
export async function test_api_todo_admin_update_enforce_uniqueness_and_length(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminJoin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword satisfies string,
      href: "https://test-suite.local/register",
      referrer: "https://test-suite.local/",
      ip: null,
    } satisfies ITodoListAdmin.IJoin,
  });
  typia.assert(adminJoin);

  // 2. Create two distinct todos as different records
  // For test purposes, create user-contextless todos via admin logic (simulate user's todos)
  // We'll generate unique UUIDs for each
  // But since the update endpoint is admin-only, and no creation endpoint is available in the template, we will simulate creating them via repeated update with different IDs
  // Create one base todo
  const baseDescription = RandomGenerator.paragraph({
    sentences: 4,
    wordMin: 4,
    wordMax: 8,
  });
  const todo1Id = typia.random<string & tags.Format<"uuid">>();
  const todo1 = await api.functional.todoList.admin.todos.update(connection, {
    todoId: todo1Id,
    body: { description: baseDescription } satisfies ITodoListTodo.IUpdate,
  });
  typia.assert(todo1);
  TestValidator.equals(
    "admin set initial todo1 description",
    todo1.description,
    baseDescription,
  );

  // Create second todo with different description
  const todo2Id = typia.random<string & tags.Format<"uuid">>();
  const todo2 = await api.functional.todoList.admin.todos.update(connection, {
    todoId: todo2Id,
    body: {
      description: RandomGenerator.paragraph({
        sentences: 6,
        wordMin: 3,
        wordMax: 7,
      }),
    } satisfies ITodoListTodo.IUpdate,
  });
  typia.assert(todo2);

  // 3. Attempt to update todo2 description to a duplicate value (the same as todo1's)
  await TestValidator.error(
    "should reject duplicate description for same user",
    async () => {
      await api.functional.todoList.admin.todos.update(connection, {
        todoId: todo2Id,
        body: { description: baseDescription } satisfies ITodoListTodo.IUpdate,
      });
    },
  );

  // 4. Attempt to update with overlong description (>255 chars)
  const longDescription = RandomGenerator.paragraph({
    sentences: 100,
    wordMin: 5,
    wordMax: 7,
  });
  await TestValidator.error(
    "should reject description exceeding 255 characters",
    async () => {
      await api.functional.todoList.admin.todos.update(connection, {
        todoId: todo2Id,
        body: {
          description: longDescription.substring(0, 256),
        } satisfies ITodoListTodo.IUpdate,
      });
    },
  );

  // 5. Attempt to update with empty string description
  await TestValidator.error(
    "should reject empty string description",
    async () => {
      await api.functional.todoList.admin.todos.update(connection, {
        todoId: todo2Id,
        body: { description: "" } satisfies ITodoListTodo.IUpdate,
      });
    },
  );

  // 6. Attempt to update with whitespace-only description
  await TestValidator.error(
    "should reject whitespace-only description",
    async () => {
      await api.functional.todoList.admin.todos.update(connection, {
        todoId: todo2Id,
        body: { description: "   \t  " } satisfies ITodoListTodo.IUpdate,
      });
    },
  );
}

