import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodoAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodoAuditLog";
import { IPageITodoListTodoAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListTodoAuditLog";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoListAdminTodosTodoIdAuditLogs(props: {
  admin: AdminPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoListTodoAuditLog.IRequest;
}): Promise<IPageITodoListTodoAuditLog.ISummary> {
  const where: Record<string, unknown> = {
    todo_id: props.todoId,
  };

  if (props.body.actor_user_id !== undefined) {
    where.actor_user_id = props.body.actor_user_id;
  }
  if (props.body.actor_admin_id !== undefined) {
    where.actor_admin_id = props.body.actor_admin_id;
  }
  if (props.body.action !== undefined && props.body.action !== null) {
    where.action = props.body.action;
  }
  if (props.body.after !== undefined || props.body.before !== undefined) {
    const createdAt: Record<string, string> = {};
    if (props.body.after !== undefined && props.body.after !== null) {
      createdAt.gte = props.body.after;
    }
    if (props.body.before !== undefined && props.body.before !== null) {
      createdAt.lte = props.body.before;
    }
    if (Object.keys(createdAt).length > 0) {
      where.created_at = createdAt;
    }
  }

  const page = props.body.page;
  const limit = props.body.limit;
  const skip = (page - 1) * limit;

  const [logs, total] = await Promise.all([
    MyGlobal.prisma.todo_list_todo_audit_logs.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.todo_list_todo_audit_logs.count({ where }),
  ]);

  const allowedActions = [
    "created",
    "updated",
    "completed",
    "uncompleted",
    "deleted",
    "restored",
    "admin_deleted",
    "admin_edited",
  ];

  const data = logs.map((log) => {
    const action = allowedActions.includes(log.action) ? log.action : "updated";
    const created_at =
      typeof log.created_at === "string" ? log.created_at : "" + log.created_at;
    return {
      id: log.id,
      todo_id: log.todo_id,
      actor_user_id: log.actor_user_id === null ? undefined : log.actor_user_id,
      actor_admin_id:
        log.actor_admin_id === null ? undefined : log.actor_admin_id,
      action: typia.assert<
        | "created"
        | "updated"
        | "completed"
        | "uncompleted"
        | "deleted"
        | "restored"
        | "admin_deleted"
        | "admin_edited"
      >(action),
      context: log.context === null ? undefined : log.context,
      created_at,
    };
  });

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IPageITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListUser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoListAdminUsers(props: {
  admin: AdminPayload;
  body: ITodoListUser.IRequest;
}): Promise<IPageITodoListUser.ISummary> {
  const {
    email,
    is_locked,
    created_at_from,
    created_at_to,
    updated_at_from,
    updated_at_to,
    page,
    page_size,
    sort_by,
    sort_order,
  } = props.body;

  // Page math
  const skip = (page - 1) * page_size;
  const take = page_size;

  // Build filter conditions for Prisma
  const where = {
    ...(typeof email === "string" &&
      email.length > 0 && {
        email: { contains: email, mode: "insensitive" as Prisma.QueryMode },
      }),
    ...(typeof is_locked === "boolean" && { is_locked }),
    ...((created_at_from || created_at_to) && {
      created_at: {
        ...(created_at_from && { gte: created_at_from }),
        ...(created_at_to && { lte: created_at_to }),
      },
    }),
    ...((updated_at_from || updated_at_to) && {
      updated_at: {
        ...(updated_at_from && { gte: updated_at_from }),
        ...(updated_at_to && { lte: updated_at_to }),
      },
    }),
  };

  // Validate sort_by and sort_order enumerations
  const validSortBy = ["created_at", "updated_at", "email"];
  const sortField = validSortBy.includes(sort_by) ? sort_by : "created_at";
  const sortDirection = sort_order === "desc" ? "desc" : "asc";

  // Fetch users with pagination/sorting
  const [users, total] = await Promise.all([
    MyGlobal.prisma.todo_list_users.findMany({
      where,
      skip,
      take,
      orderBy: { [sortField]: sortDirection },
    }),
    MyGlobal.prisma.todo_list_users.count({
      where,
    }),
  ]);

  return {
    pagination: {
      current: page,
      limit: page_size,
      records: total,
      pages: Math.ceil(total / page_size),
    },
    data: users.map((row) => ({
      id: row.id,
      email: row.email,
      is_locked: row.is_locked,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthUserJoin(props: {
  body: ITodoListUser.ICreate;
}): Promise<ITodoListUser.IAuthorized> {
  // 1. Check for existing user by email (duplicate registration not allowed)
  const duplicate = await MyGlobal.prisma.todo_list_users.findFirst({
    where: { email: props.body.email },
  });
  if (duplicate) {
    throw new HttpException("Email is already registered.", 409);
  }

  // 2. Hash plain password using PasswordUtil
  let password_hash: string;
  try {
    password_hash = await PasswordUtil.hash(props.body.password);
  } catch (err) {
    throw new HttpException("Failed to process password.", 500);
  }

  // 3. Create user
  const now = toISOStringSafe(new Date());
  const user_id = v4();
  const user = await MyGlobal.prisma.todo_list_users.create({
    data: {
      id: user_id,
      email: props.body.email,
      password_hash: password_hash,
      is_locked: false,
      created_at: now,
      updated_at: now,
    },
  });

  // 4. Create session
  const session_id = v4();
  const session_created_at = now;
  const access_expired_at = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refresh_expired_at = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const session = await MyGlobal.prisma.todo_list_user_sessions.create({
    data: {
      id: session_id,
      todo_list_user_id: user.id,
      ip: "",
      href: "",
      referrer: "",
      created_at: session_created_at,
      expired_at: access_expired_at,
    },
  });

  // 5. Issue JWT tokens. Access: 1hr, Refresh: 7d, payload must match type/contract.
  const access_token = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      created_at: session_created_at,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );
  const refresh_token = jwt.sign(
    {
      type: "user",
      id: user.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: session_created_at,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );
  const token = {
    access: access_token,
    refresh: refresh_token,
    expired_at: access_expired_at,
    refreshable_until: refresh_expired_at,
  };

  // 6. Return the IAuthorized DTO. user property is summary of just created user.
  return {
    id: user.id,
    email: user.email,
    is_locked: user.is_locked,
    created_at: toISOStringSafe(user.created_at),
    updated_at: toISOStringSafe(user.updated_at),
    token,
    user: {
      id: user.id,
      email: user.email,
      is_locked: user.is_locked,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
