import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSystemSetting";
import { IPageITodoListSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoListSystemSetting";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoListAdminSystemSettings(props: {
  admin: AdminPayload;
  body: ITodoListSystemSetting.IRequest;
}): Promise<IPageITodoListSystemSetting.ISummary> {
  const {
    key,
    description,
    sort_by = "created_at",
    order = "asc",
    created_from,
    created_to,
    updated_from,
    updated_to,
    page = 1,
    limit = 20,
  } = props.body;
  const cappedLimit = limit && limit > 100 ? 100 : (limit ?? 20);
  const skip = ((page ?? 1) - 1) * cappedLimit;
  // Build created_at range
  let createdAtCondition: Record<string, string> | undefined = undefined;
  if (created_from && created_to) {
    createdAtCondition = { gte: created_from, lte: created_to };
  } else if (created_from) {
    createdAtCondition = { gte: created_from };
  } else if (created_to) {
    createdAtCondition = { lte: created_to };
  }
  // Build updated_at range
  let updatedAtCondition: Record<string, string> | undefined = undefined;
  if (updated_from && updated_to) {
    updatedAtCondition = { gte: updated_from, lte: updated_to };
  } else if (updated_from) {
    updatedAtCondition = { gte: updated_from };
  } else if (updated_to) {
    updatedAtCondition = { lte: updated_to };
  }
  const where: Record<string, unknown> = {
    ...(key && { key: { contains: key } }),
    ...(description && { description: { contains: description } }),
    ...(createdAtCondition && { created_at: createdAtCondition }),
    ...(updatedAtCondition && { updated_at: updatedAtCondition }),
  };
  const sortField = sort_by ?? "created_at";
  const sortDir = order ?? "asc";
  const orderBy: Record<string, "asc" | "desc"> = { [sortField]: sortDir };
  const [records, total] = await Promise.all([
    MyGlobal.prisma.todo_list_system_settings.findMany({
      where,
      orderBy,
      skip,
      take: cappedLimit,
    }),
    MyGlobal.prisma.todo_list_system_settings.count({ where }),
  ]);
  return {
    pagination: {
      current: page,
      limit: cappedLimit,
      records: total,
      pages: Math.ceil(total / cappedLimit),
    },
    data: records.map((setting) => ({
      id: setting.id,
      key: setting.key,
      value: setting.value,
      description: setting.description === null ? null : setting.description,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function postTodoListUserTodos(props: {
  user: UserPayload;
  body: ITodoListTodo.ICreate;
}): Promise<ITodoListTodo> {
  const now = toISOStringSafe(new Date());
  let completedAt: string | null = null;
  if (props.body.completed) {
    completedAt = now;
  }
  try {
    const record = await MyGlobal.prisma.todo_list_todos.create({
      data: {
        id: v4(),
        user_id: props.user.id,
        description: props.body.description,
        completed: props.body.completed,
        completed_at: completedAt,
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    });
    return {
      id: record.id,
      description: record.description,
      completed: record.completed,
      completed_at: record.completed_at
        ? toISOStringSafe(record.completed_at)
        : null,
      created_at: toISOStringSafe(record.created_at),
      updated_at: toISOStringSafe(record.updated_at),
      deleted_at: record.deleted_at ? toISOStringSafe(record.deleted_at) : null,
    };
  } catch (err) {
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2002"
    ) {
      throw new HttpException(
        "Duplicate todo description for this user within allowed interval.",
        409,
      );
    }
    throw err;
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function putTodoListUserTodosTodoId(props: {
  user: UserPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoListTodo.IUpdate;
}): Promise<ITodoListTodo> {
  // Step 1: Fetch todo record
  const todo = await MyGlobal.prisma.todo_list_todos.findUnique({
    where: { id: props.todoId },
  });
  if (!todo) throw new HttpException("Todo not found.", 404);

  // Step 2: Enforce ownership/permissions
  if (todo.user_id !== props.user.id)
    throw new HttpException(
      "You do not have permission to update this todo.",
      403,
    );

  // Step 3: For soft delete, prevent user updates (deleted_at not null)
  if (todo.deleted_at != null) {
    throw new HttpException("Cannot update a deleted todo.", 403);
  }

  // Step 4: Prepare update data
  const updateData: Record<string, unknown> = {};

  // Description: optional
  if (typeof props.body.description === "string") {
    // Uniqueness check within user
    const duplicate = await MyGlobal.prisma.todo_list_todos.findFirst({
      where: {
        id: { not: props.todoId },
        user_id: props.user.id,
        description: props.body.description,
        deleted_at: null,
      },
    });
    if (duplicate) {
      throw new HttpException(
        "Duplicate description exists for this user.",
        409,
      );
    }
    updateData.description = props.body.description;
  }

  // completed: optional
  let completed_at: (string & tags.Format<"date-time">) | null | undefined =
    todo.completed_at ? toISOStringSafe(todo.completed_at) : null;
  if (
    typeof props.body.completed === "boolean" &&
    props.body.completed !== todo.completed
  ) {
    if (props.body.completed) {
      completed_at = toISOStringSafe(new Date());
      updateData.completed = true;
      updateData.completed_at = completed_at;
    } else {
      updateData.completed = false;
      updateData.completed_at = null;
      completed_at = null;
    }
  }

  // Always set updated_at
  const updated_at = toISOStringSafe(new Date());
  updateData.updated_at = updated_at;

  // Step 5: Update
  const updated = await MyGlobal.prisma.todo_list_todos.update({
    where: { id: props.todoId },
    data: updateData,
  });

  // Step 6: Map to DTO (no type assertion, use correct null/undefined for date fields)
  return {
    id: updated.id,
    description: updated.description,
    completed: updated.completed,
    completed_at: updated.completed_at
      ? toISOStringSafe(updated.completed_at)
      : null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminJoin(props: {
  body: ITodoListAdmin.IJoin;
}): Promise<ITodoListAdmin.IAuthorized> {
  // 1. Uniqueness check for email
  const existing = await MyGlobal.prisma.todo_list_admins.findFirst({
    where: { email: props.body.email },
  });
  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  // 2. Password hashing (never store plain)
  const password_hash = await PasswordUtil.hash(props.body.password);
  const now = toISOStringSafe(new Date());

  // 3. Create admin account in DB
  const adminId = v4();
  const admin = await MyGlobal.prisma.todo_list_admins.create({
    data: {
      id: adminId,
      email: props.body.email,
      password_hash,
      is_locked: false,
      created_at: now,
      updated_at: now,
    },
  });

  // 4. Create admin session
  const sessionId = v4();
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const session = await MyGlobal.prisma.todo_list_admin_sessions.create({
    data: {
      id: sessionId,
      todo_list_admin_id: admin.id,
      ip:
        props.body.ip === null || typeof props.body.ip === "undefined"
          ? ""
          : (props.body.ip satisfies string as string),
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: now,
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // 5. JWT token generation
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // 6. Return DTO: strict null/undefined fidelity
  return {
    id: admin.id,
    email: admin.email,
    is_locked: admin.is_locked,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
